theorem orbitBall_transfer (L : LengthBall G) (A : ℕ) {x x₀ : α} {t : G}
    (hx : x = t • x₀) :
    orbitBall L A x₀ ⊆ orbitBall L (A + L.length t) x

theorem OrdinarySRD.exists_global_exp_bound {ρ : ℕ → ℝ}
    (hsrd : OrdinarySRD ρ) {ε : ℝ} (hε : 0 < ε) :
    ∃ C : ℝ, 0 < C ∧ ∀ n : ℕ, ρ n ≤ C * Real.exp (ε * (n : ℝ))

theorem mul_mem_finiteRegularSpan {a b : RegularOperator G}
    (ha : a ∈ finiteRegularSpan) (hb : b ∈ finiteRegularSpan) :
    a * b ∈ finiteRegularSpan

theorem reducedGroupAlgebra_commute_rightRegular {a : RegularOperator G}
    (ha : a ∈ reducedGroupAlgebra) (g : G) :
    a * rightRegular g = rightRegular g * a
